import json

output_path = "/workspaces/incontext-if-then-2dae-claude/arxiv_search_results.json"
with open(output_path) as f:
    data = json.load(f)

# Update papers with complete metadata retrieved from arXiv
updates = {
    "2601.03269": {
        "authors": ["Vishesh Tripathi", "Uday Allu", "Biddwan Ahmed"],
        "year": 2025,
        "abstract": "Large Language Models (LLMs) have shown remarkable capabilities in natural language understanding and generation, yet their deployment in enterprise environments reveals a critical limitation: inconsistent adherence to custom instructions. This study presents a comprehensive evaluation of 13 leading LLMs across instruction compliance, response accuracy, and performance metrics in real-world RAG (Retrieval-Augmented Generation) scenarios. Through systematic testing with samples and enterprise-grade evaluation protocols, we demonstrate that instruction following varies dramatically across models, with Claude-Sonnet-4 and GPT-5 achieving the highest results. Our findings reveal the 'instruction gap' - a fundamental challenge where models excel at general tasks but struggle with precise instruction adherence required for enterprise deployment."
    },
    "2601.17789": {
        "authors": ["Yiming Su", "Kunzhao Xu", "Yanjie Gao", "Fan Yang", "Cheng Li", "Mao Yang", "Tianyin Xu"],
        "year": 2026,
        "abstract": "A fundamental problem of applying Large Language Models (LLMs) to important applications is that LLMs do not always follow instructions, and violations are often hard to observe or check. In LLM-based agentic workflows, such violations can propagate and amplify along reasoning chains, causing task failures and system incidents. This paper presents NSVIF, a neuro-symbolic framework for verifying whether an LLM's output follows the instructions used to prompt the LLM. NSVIF formulates instruction-following verification as a constraint-satisfaction problem by modeling user instructions as constraints. NSVIF models both logical and semantic constraints; constraint solving is done by a unified solver that orchestrates logical reasoning and semantic analysis. Experiments show that NSVIF significantly outperforms LLM-based approaches and provides interpretable feedback."
    },
    "2511.01014": {
        "authors": ["Bosi Wen", "Yilin Niu", "Cunxiang Wang", "Pei Ke", "Xiaoying Ling", "Ying Zhang", "Aohan Zeng", "Hongning Wang", "Minlie Huang"],
        "year": 2025,
        "abstract": "Instruction-following is a fundamental ability of Large Language Models (LLMs), requiring their generated outputs to follow multiple constraints imposed in input instructions. Numerous studies have attempted to enhance this ability through preference optimization or reinforcement learning based on reward signals from LLM-as-a-Judge. However, existing evaluation models for instruction-following still possess many deficiencies, such as substantial costs and unreliable assessments. To this end, we propose IF-CRITIC, an LLM critic for fine-grained, efficient, and reliable instruction-following evaluation. We first develop a checklist generator to decompose instructions and generate constraint checklists. Extensive experiments show that the evaluation performance of IF-CRITIC can beat strong LLM-as-a-Judge baselines, including o4-mini and Gemini-3-Pro."
    },
    "2310.07641": {
        "authors": ["Zhiyuan Zeng", "Jiatong Yu", "Tianyu Gao", "Yu Meng", "Tanya Goyal", "Danqi Chen"],
        "year": 2023,
        "abstract": "As research in large language models (LLMs) continues to accelerate, LLM-based evaluation has emerged as a scalable and cost-effective alternative to human evaluations for comparing models. This paper investigates the efficacy of these 'LLM evaluators', particularly in using them to assess instruction following, a metric that gauges how closely generated text adheres to the given instruction. We introduce a challenging meta-evaluation benchmark, LLMBar, designed to test the ability of an LLM evaluator in discerning instruction-following outputs. The authors manually curated 419 pairs of outputs, one adhering to instructions while the other diverging, yet may possess deceptive qualities that mislead an LLM evaluator. We discover that different evaluators exhibit distinct performance on LLMBar and even the highest-scoring ones have substantial room for improvement."
    },
}

for paper in data["papers"]:
    arxiv_id = paper["arxiv_id"]
    if arxiv_id in updates:
        paper.update(updates[arxiv_id])

with open(output_path, "w") as f:
    json.dump(data, f, indent=2)

print(f"Updated {len(updates)} papers with complete metadata.")
print(f"Total papers in file: {data['total_papers']}")
PYEOF
python3 /tmp/update_results.py

